package com.nypunya.assessment.entity;
import javax.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="quizzes",indexes={@Index(name="idx_quiz_course",columnList="course_id"),@Index(name="idx_quiz_trainer",columnList="trainer_id")})
public class Quiz { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=160) private String title; @Column(length=4000) private String description; @Column(name="course_id",nullable=false) private Long courseId; @Column(name="trainer_id",nullable=false) private Long trainerId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private QuizStatus status=QuizStatus.DRAFT; @Column(name="time_limit_minutes") private Integer timeLimitMinutes; @Column(name="attempt_limit") private Integer attemptLimit=1; @Column(name="created_at",nullable=false) private LocalDateTime createdAt; @PrePersist void prePersist(){if(createdAt==null)createdAt=LocalDateTime.now();} public Long getId(){return id;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public Long getCourseId(){return courseId;} public void setCourseId(Long v){courseId=v;} public Long getTrainerId(){return trainerId;} public void setTrainerId(Long v){trainerId=v;} public QuizStatus getStatus(){return status;} public void setStatus(QuizStatus v){status=v;} public Integer getTimeLimitMinutes(){return timeLimitMinutes;} public void setTimeLimitMinutes(Integer v){timeLimitMinutes=v;} public Integer getAttemptLimit(){return attemptLimit;} public void setAttemptLimit(Integer v){attemptLimit=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
